import pytest
from hypothesis import given, settings
from hypothesis import strategies as st

from dateparse import format_ymd, parse_ymd

valid_dates = st.dates().map(lambda d: (d.year, d.month, d.day))


@given(st.dates())
def test_parse_roundtrips_valid_dates(d):
    """Any real date, formatted then parsed, returns the same date."""
    s = format_ymd((d.year, d.month, d.day))
    assert parse_ymd(s) == (d.year, d.month, d.day)


@given(valid_dates)
@settings(max_examples=300)
def test_format_parse_identity_string(t):
    """For random valid dates, parse(format(t)) is the identity on strings."""
    s = format_ymd(t)
    assert s == format_ymd(parse_ymd(s))


# Explicit regression examples for the Feb 29 bug
def test_leap_day_accepted():
    assert parse_ymd("2024-02-29") == (2024, 2, 29)


def test_non_leap_feb29_rejected():
    with pytest.raises(ValueError):
        parse_ymd("2023-02-29")


def test_century_non_leap_feb29_rejected():
    with pytest.raises(ValueError):
        parse_ymd("1900-02-29")


def test_quadricentennial_feb29_accepted():
    assert parse_ymd("2000-02-29") == (2000, 2, 29)
